import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    """
    Download a ZIP file from `url`, extract it to `extract_path`, delete the ZIP,
    and return the extraction directory path.

    Returns a descriptive error message on failure.
    """
    try:
        save_dir = os.path.dirname(save_path)
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)
        os.makedirs(extract_path, exist_ok=True)
    except OSError as e:
        return f"File I/O Error: {e}"

    try:
        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)
    except urllib.error.URLError as e:
        reason = getattr(e, "reason", str(e))
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError:
                pass
        return f"URL Error: {reason}"
    except OSError as e:
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError:
                pass
        return f"File I/O Error: {e}"

    try:
        with zipfile.ZipFile(save_path, "r") as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile as e:
        return f"ZIP Error: {e}"
    except OSError as e:
        return f"File I/O Error: {e}"
    finally:
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError:
                pass

    return extract_path
